shacl_output:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ssp: <https://w3id.org/mtl-requirements/ssp#> .
@prefix ice: <http://example.com/iceregulations#> .
@prefix ssn: <http://www.w3.org/ns/ssn/> .

ice:LoadDistributionFactorShape a sh:NodeShape ;
    sh:targetNode ssp:Hull001 ;
    sh:message "Computed load-distribution factor validation failed." ;

    sh:sparql [
        sh:message "Stored factor ({?actualFactor}) does not match the calculated value ({?calculatedFactor}) based on load height and frame spacing." ;
        sh:select """
            PREFIX ssp: <https://w3id.org/mtl-requirements/ssp#>
            PREFIX ssn: <http://www.w3.org/ns/ssn/> 

            SELECT $this ?actualFactor ?calculatedFactor
            WHERE {
                # Get the stored engineering coefficient.
                ssp:loadDistribution ssn:isPropertyOf $this .
                ssp:loadDistribution ssp:hasVariableValue ?actualFactor .

                # Get source variables needed by the formula.
                $this ssn:isPropertyOf ?ship .
                ssp:loadArea ssn:isPropertyOf ?ship .
                ssp:loadArea ssp:hasVariableValue ?h .
                ssp:frameSpacing ssn:isPropertyOf ?ship .
                ssp:frameSpacing ssp:hasVariableValue ?s .

                # Calculate expected value from the regulation-style formula.
                BIND((1 - (0.2 * (?h / ?s))) AS ?calculatedFactor)

                # Fail when the stored value differs from the calculated value beyond tolerance.
                FILTER(ABS(?actualFactor - ?calculatedFactor) > 0.01)
            }
        """
    ] .
